export interface ConnectorConfig {
  /** Notion integration token with write access to the target database. */
  notionApiKey: string
  /** The Notion database ID for the 'Signed' database. */
  notionDatabaseId: string
  /** The Pipedrive stage ID that represents the Won stage. */
  pipedriveWonStageId: number
  /** Injected fetch for testing; defaults to global fetch. */
  fetch?: typeof fetch
}

export interface PipedriveWebhookPayload {
  data: {
    title: string
    value: number
    owner_id: number
    close_time: string
    stage_id: number
    status: string
  }
  previous: unknown
  meta: {
    action: string
    entity: string
    entity_id: string
    id: string
    timestamp: string
    version: string
    webhook_id: string
    webhook_owner_id: string
    change_source: string
    attempt: number
    host: string
    type: string
    user_id: string
    company_id: string
    correlation_id: string
    is_bulk_edit: boolean
  }
}

export interface HandleResult {
  notionPageId: string
}

function validatePayload(payload: unknown): asserts payload is PipedriveWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (!p.data || typeof p.data !== 'object') {
    throw new Error('Missing required field: data')
  }
  const data = p.data as Record<string, unknown>
  const requiredDataFields = ['title', 'value', 'owner_id', 'close_time', 'stage_id', 'status']
  for (const field of requiredDataFields) {
    if (!(field in data)) {
      throw new Error(`Missing required field: data.${field}`)
    }
  }
  if (!p.meta || typeof p.meta !== 'object') {
    throw new Error('Missing required field: meta')
  }
  const meta = p.meta as Record<string, unknown>
  if (!('action' in meta)) {
    throw new Error('Missing required field: meta.action')
  }
}

function isWonDeal(payload: PipedriveWebhookPayload, wonStageId: number): boolean {
  return (
    payload.meta.action === 'change' &&
    payload.data.status === 'won' &&
    payload.data.stage_id === wonStageId
  )
}

function extractDatePart(isoString: string): string {
  // ISO string like "2024-06-15T10:30:00Z" -> "2024-06-15"
  const match = isoString.match(/^(\d{4}-\d{2}-\d{2})/)
  if (!match) {
    throw new Error(`Invalid close_time format: ${isoString}`)
  }
  return match[1]
}

async function createNotionPage(
  config: ConnectorConfig,
  properties: Record<string, unknown>
): Promise<string> {
  const fetchFn = config.fetch ?? fetch
  const url = 'https://api.notion.com/v1/pages'
  const body = {
    parent: { database_id: config.notionDatabaseId },
    properties,
  }
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.notionApiKey}`,
      'Notion-Version': '2022-06-28',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })
  if (!response.ok) {
    throw new Error(`Notion API error: ${response.status} ${response.statusText} at POST ${url}`)
  }
  const json = (await response.json()) as { id: string }
  return json.id
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const typedPayload = payload as PipedriveWebhookPayload

  if (!isWonDeal(typedPayload, config.pipedriveWonStageId)) {
    throw new Error('Deal is not a won deal or stage does not match configured Won stage')
  }

  const closeDate = extractDatePart(typedPayload.data.close_time)

  const properties = {
    'Deal Name': {
      title: [{ text: { content: typedPayload.data.title } }],
    },
    'Deal Value': {
      number: typedPayload.data.value,
    },
    Owner: {
      people: [{ object: 'user', id: String(typedPayload.data.owner_id) }],
    },
    'Close Date': {
      date: { start: closeDate },
    },
  }

  const notionPageId = await createNotionPage(config, properties)
  return { notionPageId }
}

